&lt;!DOCTYPE html&gt;
&lt;html&gt;
  &lt;head&gt;
    &lt;script src="https://cdn.front.nu/nightly/front.js"&gt;&lt;/script&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;h1 id="message" settext="Hello from FTML" color="tomato" bgcolor="white"&gt;&lt;/h1&gt;
  &lt;/body&gt;
&lt;/html&gt;

&lt;!DOCTYPE html&gt;
&lt;html&gt;
  &lt;head&gt;
    &lt;script src="https://cdn.front.nu/nightly/front.js"&gt;&lt;/script&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;label for="nameInput"&gt;Your name&lt;/label&gt;
    &lt;input id="nameInput" setvalue="Front"&gt;
    &lt;p id="nameOutput" bindfield="name:#nameInput" settext="Hello {name}"&gt;&lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;

&lt;!DOCTYPE html&gt;
&lt;html&gt;
  &lt;head&gt;
    &lt;script src="https://cdn.front.nu/nightly/front.js"&gt;&lt;/script&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;button click="toggledisplay:#message"&gt;Toggle message&lt;/button&gt;
    &lt;p id="message"&gt;This message can be toggled.&lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;
